const payload = $json.body ?? $json;
const item = payload.item ?? payload;
const phone = String(payload.phone ?? payload.to ?? item.phone ?? '').replace(/\D/g, '');
const title = String(item.title ?? 'Lembrete Zap-it').trim();
const content = String(item.content ?? '').trim();
const reminderAt = item.reminderAt ?? payload.reminderAt;

if (!phone) {
  throw new Error('Informe o telefone em formato internacional. Exemplo: 5511999999999');
}

if (!reminderAt) {
  throw new Error('Informe reminderAt em ISO 8601. Exemplo: 2026-05-25T15:00:00-03:00');
}

const dueAt = new Date(reminderAt);

if (Number.isNaN(dueAt.getTime())) {
  throw new Error('reminderAt inválido. Use uma data ISO 8601.');
}

const priority = item.priority ? `Prioridade: ${item.priority}` : '';
const category = item.category ? `Categoria: ${item.category}` : '';
const cardUrl = payload.cardUrl || item.cardUrl || '';
const details = [content, priority, category, cardUrl ? `Abrir no Zap-it: ${cardUrl}` : ''].filter(Boolean).join('\n');
const message = [`Lembrete Zap-it`, '', title, details].filter(Boolean).join('\n');

return [
  {
    json: {
      itemId: item.id ?? payload.itemId ?? null,
      title,
      content,
      phone,
      reminderAt: dueAt.toISOString(),
      message,
      source: 'zap-it'
    }
  }
];

return [
  {
    json: {
      ok: true,
      itemId: $json.itemId ?? null,
      title: $json.title,
      deliveredAt: new Date().toISOString(),
      whatsappResponse: $json
    }
  }
];
